-- Fakt kartochkalari orqa tomonining ruscha matni — 69-partiya:
-- Mahmud Zamaxshariy, Mirtemir, Muhammad Yusuf.

UPDATE fact_cards SET detail_ru = 'Замахшари родился 18 марта 1075 года в хорезмском селении Замахшар; нисба «Замахшари» и взята от названия этого селения. Семья его была набожной, и первое образование он получил у отца. Источник: Ziyouz.com, раздел «Энциклопедические учёные и полководцы».' WHERE id = 1877;
UPDATE fact_cards SET detail_ru = 'В юности Замахшари упал с коня и охромел на одну ногу. Отец хотел, чтобы он овладел ремеслом портного, но будущий учёный пошёл путём науки. Источник: Ziyouz.com, раздел «Энциклопедические учёные и полководцы».' WHERE id = 1878;
UPDATE fact_cards SET detail_ru = 'Замахшари брал уроки у таких учёных, как Абу Мудар Исфахани, Абумансур Наср Хариси, Абусаад Шаккани и Абульхаттаб ибн Абульбатр. Он глубоко изучил арабский язык и словесность, богословские науки, а также искусство каллиграфии, ценимое среди учёных того времени. Источник: Ziyouz.com, раздел «Энциклопедические учёные и полководцы».' WHERE id = 1879;
UPDATE fact_cards SET detail_ru = 'В 1100–1122 и 1127–1139 годах Замахшари странствовал по мусульманскому Востоку и побывал в таких городах, как Мерв, Нишапур, Исфахан, Багдад, Дамаск и Мекка. В 1139 году он вернулся на родину и жил здесь до конца своих дней. Источник: Ziyouz.com, раздел «Энциклопедические учёные и полководцы».' WHERE id = 1880;
UPDATE fact_cards SET detail_ru = 'За то, что Замахшари жил и творил в Мекке, он был удостоен почётного имени «Джаруллах» — «сосед Божий». Чтили его и такими высокими именами, как «Устаз уд-дунья» и «Фахр-и Хорезм». Источник: Ziyouz.com, раздел «Энциклопедические учёные и полководцы».' WHERE id = 1881;
UPDATE fact_cards SET detail_ru = '«Аль-Кашшаф» написан в 1132–1134 годах в Мекке и посвящён толкованию Корана. Существует около ста рукописей сочинения, и оно употреблялось как учебное пособие в таких университетах, как Аль-Азхар. Источник: Ziyouz.com, раздел «Энциклопедические учёные и полководцы».' WHERE id = 1882;
UPDATE fact_cards SET detail_ru = '«Мукаддимат уль-адаб» (1137) посвящён хорезмшаху Атсызу и состоит из пяти больших частей: об именах, глаголах, союзах, изменениях имён и изменениях глаголов. Персидские и тюркские переводы арабских слов в нём ценны для узбекской исторической лексикологии. Источник: Ziyouz.com, раздел «Энциклопедические учёные и полководцы».' WHERE id = 1883;
UPDATE fact_cards SET detail_ru = '«Аль-Муфассаль» (1121) — книга, в которой подробно изложена грамматика арабского языка; она снискала известность и на мусульманском Востоке, и в западных странах. Это одно из самых признанных сочинений Замахшари в языкознании. Источник: Ziyouz.com, раздел «Энциклопедические учёные и полководцы».' WHERE id = 1884;
UPDATE fact_cards SET detail_ru = 'Замахшари создал около пятидесяти сочинений в разных областях науки, из которых до нас дошло двадцать пять. Среди них — «Аль-Мустакса фи-ль-амсаль», где истолкованы около 3500 арабских пословиц, «Асас аль-балага» по словарному делу, «Раби уль-абрар», состоящее из рассказов, и «Китаб аль-джибаль» по географии. У него было более двухсот учеников. Источник: Ziyouz.com, раздел «Энциклопедические учёные и полководцы».' WHERE id = 1885;
UPDATE fact_cards SET detail_ru = 'Замахшари умер в 1144 году на территории нынешнего Куня-Ургенча и там же погребён. Арабский путешественник XIV века Ибн Баттута написал в своих записках, что своими глазами видел его мавзолей с купольной кровлей. Рукописи учёного хранятся в Германии, Египте, Турции, Иране, Франции и России. Источник: Ziyouz.com, раздел «Энциклопедические учёные и полководцы».' WHERE id = 1886;

UPDATE fact_cards SET detail_ru = 'Миртемир Турсунов родился 30 мая 1910 года в селении Икон, относящемся к городу Туркестану. В детстве он учился сперва в школе старого образца, затем в ташкентской образцовой школе имени Алмаи. Источник: Ziyouz.com, статья «Миртемир (1910–1978)».' WHERE id = 2227;
UPDATE fact_cards SET detail_ru = 'Получив образование в школе старого образца (1919–1920), Миртемир приехал в Ташкент и учился в образцовой школе имени Алмаи (1920–1923), а затем, в 1925–1929 годах, в Узбекском мужском училище. Источник: Ziyouz.com, статья «Миртемир (1910–1978)».' WHERE id = 2228;
UPDATE fact_cards SET detail_ru = 'Первая книга Миртемира «В объятиях лучей» была издана в 1928 году в жанре свободного стиха. Позже вышли и его стихотворные сборники «Победа» (1929), «Мои кипения» и «Набат» (1932). Источник: Ziyouz.com, статья «Миртемир (1910–1978)».' WHERE id = 2229;
UPDATE fact_cards SET detail_ru = '«Портрет» — лирическая повесть Миртемира, написанная в 1956–1957 годах в Каракалпакстане; она вошла в сборник «Каракалпакская тетрадь» (1957). Это сочинение сильно повлияло на усиление в 60–70-е годы внимания к жанру поэмы в узбекской поэзии и на созревание жанра лирической поэмы. Источник: Ziyouz.com, статья «Миртемир (1910–1978)».' WHERE id = 2230;
UPDATE fact_cards SET detail_ru = 'Миртемир — автор поэм «Барат» (1930), «Хидир» (1932), «Дилькушо», «Дочь воды» (1937), «На свадьбе моей Ойсанам» (1938) и «Кузи» (1939). Изданы и его стихотворные сборники «Победа» (1929), «Мои кипения» и «Набат» (1932). Источник: Ziyouz.com, статья «Миртемир (1910–1978)».' WHERE id = 2231;
UPDATE fact_cards SET detail_ru = 'Миртемир переложил на узбекский язык стихи А. С. Пушкина, поэму Н. А. Некрасова «Кому на Руси жить хорошо», сочинение Руставели «Витязь в тигровой шкуре», образцы творчества Абая, Махтумкули и Бердаха, а также киргизский народный эпос «Манас». Источник: Ziyouz.com, статья «Миртемир (1910–1978)».' WHERE id = 2232;
UPDATE fact_cards SET detail_ru = 'В 1971 году Миртемир был удостоен звания народного поэта Узбекистана, а в 1977-м — Государственной премии Каракалпакстана имени Бердаха. После его смерти, в 1979 году, ему была присуждена Государственная премия Узбекистана имени Хамзы, а в 2002 году — орден «За великие заслуги». Источник: Ziyouz.com, статья «Миртемир (1910–1978)».' WHERE id = 2233;
UPDATE fact_cards SET detail_ru = 'Миртемир умер 25 января 1978 года в Ташкенте. Память о нём чтили и после смерти: в 1979 году ему была присуждена Государственная премия Узбекистана имени Хамзы, а в 2002 году — орден «За великие заслуги». Источник: Ziyouz.com, статья «Миртемир (1910–1978)».' WHERE id = 2234;

UPDATE fact_cards SET detail_ru = 'Мухаммад Юсуф родился 26 апреля 1954 года в Мархаматском районе Андижанской области. Позже он стал одним из самых любимых поэтов Узбекистана. Источник: Ziyouz.com, страница «Мухаммад Юсуф (1954–2001)».' WHERE id = 2235;
UPDATE fact_cards SET detail_ru = 'В 1978 году он окончил факультет Института русского языка и литературы. Затем он работал в области творчества и печати. Источник: Ziyouz.com.' WHERE id = 2236;
UPDATE fact_cards SET detail_ru = 'Первый сборник поэта «Знакомые тополя» был напечатан в 1985 году. Затем изданы сборники «Есть у меня слово к соловью» (1987) и «Мольба» (1988). Источник: Ziyouz.com.' WHERE id = 2237;
UPDATE fact_cards SET detail_ru = 'Изданы такие его сборники, как «Спящая девушка» (1989), «Корабль любви» (1990), «Ласковая лань» (1995), «Унесу в моё небо» (1998). После его смерти, в 2004 году, была напечатана и книга «Ты велика, моя родина». Источник: Ziyouz.com.' WHERE id = 2238;
UPDATE fact_cards SET detail_ru = 'В творчестве поэта главенствовали образы Родины, матерей и трудолюбивого народа. Такие его стихи, как «Матушка», «Моя родина», «Любовь», известны в народе. Источник: Ziyouz.com и УзА.' WHERE id = 2239;
UPDATE fact_cards SET detail_ru = 'Мухаммад Юсуф работал в газете «Тошкент окшоми». Здесь он работал вместе с поэтом Сирожиддином Сайидом. Источник: УзА — статья «Мухаммад Юсуф — обладатель вечно живой поэзии».' WHERE id = 2240;
UPDATE fact_cards SET detail_ru = 'В 1998 году Мухаммаду Юсуфу было присвоено звание народного поэта Узбекистана. Это знак того, что его поэзию признал весь народ. Источник: Ziyouz.com.' WHERE id = 2241;
UPDATE fact_cards SET detail_ru = 'Мухаммад Юсуф умер 31 июля 2001 года в Элликкалинском районе. Память о нём чтят по всей стране, проводятся вечера памяти, посвящённые его рождению. Источник: Ziyouz.com и УзА.' WHERE id = 2242;
